from math import gcd

class Rational:
    def __init__(self, numer, denom):
        if denom == 0:
            raise ZeroDivisionError("Denominator cannot be zero")
        # Ensure integers
        self.numer = int(numer)
        self.denom = int(denom)
        self._reduce()

    def _reduce(self):
        # Handle zero numerator: standard form is 0/1
        if self.numer == 0:
            self.denom = 1
            return
        g = gcd(self.numer, self.denom)
        self.numer //= g
        self.denom //= g
        # Ensure denominator positive
        if self.denom < 0:
            self.numer = -self.numer
            self.denom = -self.denom

    def __eq__(self, other):
        if not isinstance(other, Rational):
            return NotImplemented
        return self.numer == other.numer and self.denom == other.denom

    def __repr__(self):
        return f'{self.numer}/{self.denom}'

    def __add__(self, other):
        if not isinstance(other, Rational):
            return NotImplemented
        n = self.numer * other.denom + other.numer * self.denom
        d = self.denom * other.denom
        return Rational(n, d)

    def __sub__(self, other):
        if not isinstance(other, Rational):
            return NotImplemented
        n = self.numer * other.denom - other.numer * self.denom
        d = self.denom * other.denom
        return Rational(n, d)

    def __mul__(self, other):
        if not isinstance(other, Rational):
            return NotImplemented
        n = self.numer * other.numer
        d = self.denom * other.denom
        return Rational(n, d)

    def __truediv__(self, other):
        if not isinstance(other, Rational):
            return NotImplemented
        if other.numer == 0:
            raise ZeroDivisionError("Cannot divide by zero")
        n = self.numer * other.denom
        d = self.denom * other.numer
        # Division may flip sign of denominator; Rational will normalize
        return Rational(n, d)

    def __abs__(self):
        return Rational(abs(self.numer), abs(self.denom))

    def __pow__(self, power):
        # Integer powers -> return Rational
        if isinstance(power, int):
            if power == 0:
                # x**0 is 1 for any x (including 0 in Python semantics)
                return Rational(1, 1)
            if power > 0:
                return Rational(self.numer ** power, self.denom ** power)
            # power < 0
            if self.numer == 0:
                raise ZeroDivisionError("0 cannot be raised to a negative power")
            p = -power
            return Rational(self.denom ** p, self.numer ** p)
        # Float (or other real) powers -> return float
        try:
            # Use float conversion to compute real power
            return (float(self.numer) ** float(power)) / (float(self.denom) ** float(power))
        except Exception:
            # If computation not possible, re-raise as ValueError
            raise

    def __rpow__(self, base):
        # base ** (a/b) -> return float (or complex if base negative and fraction not integer)
        exp = self.numer / self.denom
        return float(base) ** exp
